 GradientDrawable shape(int color,int radius){GradientDrawable g=new GradientDrawable();g.setColor(color);g.setCornerRadius(dpv(radius));g.setStroke(dpv(1),Color.rgb(45,63,88));return g;}int dpv(int x){return(int)(x*getResources().getDisplayMetrics().density+.5f);}int sectionColor(String title){String k=title==null?"":title.toUpperCase(Locale.ROOT);if(k.contains("HEALTH"))return VGREEN;if(k.contains("MEDICATION"))return VPINK;if(k.contains("MEAL"))return VCYAN;if(k.contains("WORKOUT"))return VORANGE;if(k.contains("MEMORY")||k.contains("MEMORIES"))return VYELLOW;if(k.contains("WORK")||k.contains("MONEY"))return VBLUE;if(k.contains("REWARD"))return VPINK;if(k.contains("CALENDAR"))return VCYAN;if(k.contains("BACKUP"))return VGREEN;if(k.contains("SCHEDULE"))return VBLUE;return VPURPLE;}
