 static class S{int score,done,missed,pending,possible,earned,penalty;}
 S period(LocalDate start,LocalDate end){S o=new S();LocalDate track;try{track=LocalDate.parse(s.get("tracking_start",LocalDate.now().toString()));}catch(Exception e){track=LocalDate.now();}if(start.isBefore(track))start=track;ZonedDateTime now=ZonedDateTime.now();for(LocalDate d=start;!d.isAfter(end);d=d.plusDays(1)){int dw=d.getDayOfWeek().getValue();for(Map<String,String>task:s.q("SELECT * FROM tasks WHERE active=1")){if(!match(task.get("days"),dw))continue;int pts=pi(task.get("points"),0),sm=pi(task.get("start_min"),0),du=pi(task.get("duration"),0);ZonedDateTime due=d.atTime(sm/60,sm%60).plusMinutes(Math.max(0,du)).atZone(ZoneId.systemDefault());List<Map<String,String>> l=s.q("SELECT status,penalty_points FROM task_log WHERE day=? AND task_id=?",d.toString(),task.get("id"));boolean count=d.isBefore(LocalDate.now())||!l.isEmpty()||!due.isAfter(now);if(!count)continue;o.possible+=pts;if(l.isEmpty()){o.pending++;continue;}String st=l.get(0).get("status");o.penalty+=pi(l.get(0).get("penalty_points"),0);if("DONE".equals(st)){o.done++;o.earned+=pts;}else o.missed++;}}if(o.possible==0)o.score=100;else o.score=Math.max(0,Math.min(100,(int)Math.round(100.0*(o.earned-o.penalty)/o.possible)));return o;}
 boolean match(String days,int d){return days!=null&&Arrays.asList(days.split(",")).contains(String.valueOf(d));}int pi(String x,int d){try{return Integer.parseInt(x);}catch(Exception e){return d;}}long pl(String x,long d){try{return Long.parseLong(x);}catch(Exception e){return d;}}
 void render(LinearLayout box,String mode){while(box.getChildCount()>1)box.removeViewAt(1);LocalDate e=LocalDate.now(),st=e;if("WEEK".equals(mode))st=e.with(DayOfWeek.MONDAY);else if("MONTH".equals(mode))st=e.withDayOfMonth(1);S q=period(st,e);ProgressRingView r=new ProgressRingView(this);r.setProgressData(q.score,q.score>=80?"STRONG":q.score>=55?"KEEP PUSHING":"NEEDS ATTENTION");box.addView(r,new LinearLayout.LayoutParams(-1,dpv(220)));TextView tt=t(mode+" SUCCESS SCORE",13,true);tt.setTextColor(q.score>=80?VGREEN:q.score>=55?VORANGE:VRED);tt.setGravity(Gravity.CENTER);box.addView(tt);TextView z=sub(q.done+" done  •  "+q.missed+" missed  •  "+q.pending+" due/pending  •  -"+q.penalty+" penalty points");z.setGravity(Gravity.CENTER);box.addView(z);TextView sk=sub("Strong-day streak: "+streak()+" day"+(streak()==1?"":"s"));sk.setGravity(Gravity.CENTER);box.addView(sk);}
 int streak(){int n=0;LocalDate d=LocalDate.now();for(int i=0;i<365;i++){S q=period(d,d);if(q.possible==0){d=d.minusDays(1);continue;}if(q.score>=70){n++;d=d.minusDays(1);}else break;}return n;}
 String norm(String c){if(c==null)return"MIND";c=c.toUpperCase(Locale.ROOT);if(c.contains("HEALTH")||c.contains("MED"))return"HEALTH";if(c.contains("FAMILY"))return"FAMILY";if(c.contains("WORK")||c.contains("MONEY")||c.contains("BUSINESS"))return"WORK";if(c.contains("BODY")||c.contains("FIT")||c.contains("EXER")||c.contains("WORKOUT"))return"BODY";if(c.contains("JOY")||c.contains("MEMORY")||c.contains("FUN"))return"JOY";return"MIND";}
 void compass(LinearLayout x){LinearLayout o=colorCard(VBLUE),in=ci(o);in.addView(t("LIFE COMPASS — TODAY",13,true));LinkedHashMap<String,int[]> map=new LinkedHashMap<>();for(String c:new String[]{"HEALTH","FAMILY","WORK","BODY","MIND","JOY"})map.put(c,new int[]{0,0});LocalDate d=LocalDate.now();for(Map<String,String>task:s.q("SELECT * FROM tasks WHERE active=1")){if(!match(task.get("days"),d.getDayOfWeek().getValue()))continue;String k=norm(task.get("category"));int pts=pi(task.get("points"),0);map.get(k)[1]+=pts;List<Map<String,String>> l=s.q("SELECT status FROM task_log WHERE day=? AND task_id=?",d.toString(),task.get("id"));if(!l.isEmpty()&&"DONE".equals(l.get(0).get("status")))map.get(k)[0]+=pts;}for(Map.Entry<String,int[]>e:map.entrySet()){TextView lab=sub(e.getKey()+"   "+(e.getValue()[1]==0?"—":100*e.getValue()[0]/Math.max(1,e.getValue()[1])+"%"));in.addView(lab);ProgressBar pb=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);pb.setMax(100);pb.setProgress(e.getValue()[1]==0?0:100*e.getValue()[0]/Math.max(1,e.getValue()[1]));pb.setProgressTintList(ColorStateList.valueOf(cc(e.getKey())));in.addView(pb,new LinearLayout.LayoutParams(-1,dpv(8)));}x.addView(o);}
 String nextAction(){int now=LocalTime.now().getHour()*60+LocalTime.now().getMinute();Map<String,String> over=null,next=null;int overScore=-9999,nextStart=9999;for(Map<String,String>m:s.q("SELECT * FROM tasks WHERE active=1 ORDER BY start_min")){if(!match(m.get("days"),LocalDate.now().getDayOfWeek().getValue()))continue;if(!s.q("SELECT 1 FROM task_log WHERE day=? AND task_id=?",LocalDate.now().toString(),m.get("id")).isEmpty())continue;int st=pi(m.get("start_min"),0),due=st+pi(m.get("duration"),0);if(now>=st&&now-due>overScore){over=m;overScore=now-due;}else if(st>now&&st<nextStart){next=m;nextStart=st;}}if(over!=null)return"DO NOW • "+over.get("title");if(next!=null)return hm(next.get("start_min"))+" • "+next.get("title");return"Create one meaningful memory, prepare tomorrow, or rest on purpose.";}
 @Override void route(String k){if("GOALS".equals(k)){goals();return;}if("MEDIA VAULT".equals(k)){mediaVault();return;}super.route(k);}
 @Override void today(){LinearLayout x=base("TODAY","Tasks get a 60-minute grace hour after their scheduled end. Reminders arrive at +15, +30 and +45 minutes; +60 auto-marks missed.");header(x);int now=LocalTime.now().getHour()*60+LocalTime.now().getMinute();for(Map<String,String>m:s.q("SELECT * FROM tasks WHERE active=1 ORDER BY start_min")){if(!match(m.get("days"),LocalDate.now().getDayOfWeek().getValue()))continue;long id=pl(m.get("id"),0);int due=pi(m.get("start_min"),0)+pi(m.get("duration"),0);List<Map<String,String>> log=s.q("SELECT status,reason,penalty_points FROM task_log WHERE day=? AND task_id=?",LocalDate.now().toString(),String.valueOf(id));String status=log.isEmpty()?"PENDING":log.get(0).get("status");int color="DONE".equals(status)?VGREEN:status.contains("MISSED")?VRED:cc(m.get("category"));LinearLayout o=colorCard(color),in=ci(o);TextView h=t(hm(m.get("start_min"))+"  "+m.get("title"),17,true);h.setTextColor(color);in.addView(h);in.addView(sub(m.get("category")+" • "+m.get("duration")+" min • +"+m.get("points")+" points"));String info="Status: "+status;if(log.isEmpty()&&now>due&&now<=due+60)info+=" • OVERDUE • "+(due+60-now)+" min grace left";TextView si=sub(info);if(log.isEmpty()&&now>due)si.setTextColor(VORANGE);in.addView(si);LinearLayout row=new LinearLayout(this);Button done=new Button(this);done.setText("DONE");done.setTextColor(Color.rgb(5,20,25));done.setBackground(shape(VGREEN,12));Button sno=dark("SNOOZE 10"),cant=dark("I CANNOT");row.addView(done,new LinearLayout.LayoutParams(0,-2,1));row.addView(sno,new LinearLayout.LayoutParams(0,-2,1));row.addView(cant,new LinearLayout.LayoutParams(0,-2,1));in.addView(row);done.setOnClickListener(v->{s.logTaskForDay(id,LocalDate.now().toString(),"DONE","",0);today();});sno.setOnClickListener(v->{snooze(id,10);toast("Snoozed 10 minutes");});cant.setOnClickListener(v->cannotV15(id,m));x.addView(o);}setContentView(scroll(x));}
 void cannotV15(long id,Map<String,String>task){String[]r={"Emergency","Sick / unwell","Family emergency","Schedule conflict","I avoided it","Other"};new AlertDialog.Builder(this).setTitle("Why can't you do this?").setItems(r,(d,w)->{String reason=r[w];int pp="I avoided it".equals(reason)?pi(task.get("points"),5):0;s.logTaskForDay(id,LocalDate.now().toString(),"MISSED",reason,pp);if(pp>0)addPenalty(reason+": "+task.get("title"),pi(task.get("penalty"),100));today();}).show();}
 void goals(){LinearLayout x=base("LIFE GOALS","Make the future measurable: target, current value, deadline and why it matters.");header(x);Button add=new Button(this);add.setText("+ Add goal");add.setTextColor(Color.WHITE);add.setBackground(shape(VPURPLE,14));x.addView(add);add.setOnClickListener(v->editGoal(null));for(Map<String,String>m:s.q("SELECT * FROM goals ORDER BY status,title")){LinearLayout o=colorCard(VPURPLE),in=ci(o);in.addView(t(m.get("title"),17,true));in.addView(sub(m.get("area")+" • Current: "+m.get("current_value")+" "+m.get("unit")+" • Target: "+m.get("target_value")+" "+m.get("unit")+" • "+m.get("target_date")));if(!m.get("why").isEmpty())in.addView(sub("Why: "+m.get("why")));Button ed=dark("Edit");in.addView(ed);ed.setOnClickListener(v->editGoal(m));x.addView(o);}setContentView(scroll(x));}
 void editGoal(Map<String,String>m){EditText a=e("Goal title"),area=e("Area: Health / Family / Work / Money / Mind / Joy"),tv=e("Target value"),cv=e("Current value"),u=e("Unit"),date=e("Target date YYYY-MM-DD"),why=e("Why this matters"),st=e("ACTIVE / ACHIEVED / PAUSED");if(m!=null){a.setText(m.get("title"));area.setText(m.get("area"));tv.setText(m.get("target_value"));cv.setText(m.get("current_value"));u.setText(m.get("unit"));date.setText(m.get("target_date"));why.setText(m.get("why"));st.setText(m.get("status"));}else st.setText("ACTIVE");LinearLayout b=base("Goal",null);for(View z:new View[]{a,area,tv,cv,u,date,why,st})b.addView(z);new AlertDialog.Builder(this).setTitle("Life Goal").setView(scroll(b)).setPositiveButton("Save",(q,w)->{ContentValues c=new ContentValues();c.put("title",a.getText().toString());c.put("area",area.getText().toString());c.put("target_value",tv.getText().toString());c.put("current_value",cv.getText().toString());c.put("unit",u.getText().toString());c.put("target_date",date.getText().toString());c.put("why",why.getText().toString());c.put("status",st.getText().toString());if(m==null)s.insert("goals",c);else s.update("goals",pl(m.get("id"),0),c);goals();}).setNegativeButton("Cancel",null).show();}
 void mediaVault(){LinearLayout x=base("MEDIA VAULT","Open the camera from Life OS; the file is automatically saved to the selected Life OS category.");header(x);String[][] cats={{"Family Memory","Family Memories"},{"Body Progress","Health Progress"},{"Workout","Workouts"},{"Meal","Meals"},{"General","Life Vault"}};for(String[]a:cats){LinearLayout r=new LinearLayout(this);Button p=dark(a[0]+" Photo"),v=dark(a[0]+" Video");r.addView(p,new LinearLayout.LayoutParams(0,-2,1));r.addView(v,new LinearLayout.LayoutParams(0,-2,1));x.addView(r);p.setOnClickListener(z->capture(a[1],false));v.setOnClickListener(z->capture(a[1],true));}for(Map<String,String>m:s.q("SELECT * FROM media ORDER BY created_at DESC")){LinearLayout o=colorCard(VPURPLE),in=ci(o);in.addView(t(m.get("category")+" • "+(m.get("mime").startsWith("video")?"VIDEO":"PHOTO"),16,true));in.addView(sub(m.get("created_at")+(m.get("caption").isEmpty()?"":"\n"+m.get("caption"))));Button open=dark("Open");in.addView(open);open.setOnClickListener(v->{try{Uri u=Uri.parse(m.get("uri"));Intent i=new Intent(Intent.ACTION_VIEW);i.setDataAndType(u,m.get("mime"));i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(i);}catch(Exception ex){toast("Media file unavailable");}});x.addView(o);}setContentView(scroll(x));}
 void capture(String cat,boolean video){try{mediaCategory=cat;mediaMime=video?"video/mp4":"image/jpeg";ContentValues v=new ContentValues();v.put(MediaStore.MediaColumns.DISPLAY_NAME,"LifeOS_"+System.currentTimeMillis()+(video?".mp4":".jpg"));v.put(MediaStore.MediaColumns.MIME_TYPE,mediaMime);v.put(MediaStore.MediaColumns.RELATIVE_PATH,(video?"Movies":"Pictures")+"/Suresh Life OS/"+cat);mediaUri=getContentResolver().insert(video?MediaStore.Video.Media.EXTERNAL_CONTENT_URI:MediaStore.Images.Media.EXTERNAL_CONTENT_URI,v);Intent i=new Intent(video?MediaStore.ACTION_VIDEO_CAPTURE:MediaStore.ACTION_IMAGE_CAPTURE);i.putExtra(MediaStore.EXTRA_OUTPUT,mediaUri);i.addFlags(Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_READ_URI_PERMISSION);i.setClipData(ClipData.newRawUri("Life OS",mediaUri));startActivityForResult(i,video?MV:MP);}catch(Exception e){alert("Camera error",e.getMessage());}}
 @Override protected void onActivityResult(int req,int res,Intent data){if(req==MP||req==MV){if(mediaUri!=null){if(res==RESULT_OK){ContentValues v=new ContentValues();v.put("created_at",ZonedDateTime.now().toString());v.put("category",mediaCategory);v.put("mime",mediaMime);v.put("uri",mediaUri.toString());v.put("caption","");s.insert("media",v);toast("Saved to "+mediaCategory);}else try{getContentResolver().delete(mediaUri,null,null);}catch(Exception ignored){}mediaUri=null;}return;}super.onActivityResult(req,res,data);}
